  // --- Cookie & Preference Persistence Helpers ---
  function setPrefCookie(name, value, days = 365) {
    const expires = new Date(Date.now() + days * 864e5).toUTCString();
    document.cookie = name + '=' + encodeURIComponent(value) + '; expires=' + expires + '; path=/; SameSite=Lax';
  }

  function getPrefCookie(name) {
    const matches = document.cookie.match(new RegExp('(?:^|; )' + name.replace(/([.$?*|{}()[]\/+^])/g, '\$1') + '=([^;]*)'));
    return matches ? decodeURIComponent(matches[1]) : null;
  }

  function savePreference(key, val) {
    try {
      localStorage.setItem('derya_' + key, val);
      setPrefCookie('derya_' + key, val);
    } catch (e) {}
  }

  function loadPreference(key, defaultVal) {
    try {
      const cookieVal = getPrefCookie('derya_' + key);
      if (cookieVal !== null) return cookieVal;
      const localVal = localStorage.getItem('derya_' + key);
      if (localVal !== null) return localVal;
    } catch (e) {}
    return defaultVal;
  }

