  function createStereoBrownNoiseBuffer(ctx, durationSec) {
    const sampleRate = ctx.sampleRate;
    const bufferSize = sampleRate * durationSec;
    const buffer = ctx.createBuffer(2, bufferSize, sampleRate);
    const left = buffer.getChannelData(0);
    const right = buffer.getChannelData(1);
    let lastLeft = 0, lastRight = 0;
    for (let i = 0; i < bufferSize; i++) {
      const whiteL = Math.random() * 2 - 1;
      const whiteR = Math.random() * 2 - 1;
      lastLeft = (lastLeft + (0.022 * whiteL)) / 1.018;
      lastRight = (lastRight + (0.022 * whiteR)) / 1.018;
      left[i] = lastLeft * 3.2;
      right[i] = lastRight * 3.2;
    }
    return buffer;
  }

  function createWhiteNoiseBuffer(ctx, durationSec) {
    const sampleRate = ctx.sampleRate;
    const bufferSize = Math.floor(sampleRate * durationSec);
    const buffer = ctx.createBuffer(1, bufferSize, sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  function createGranularFoamBuffer(ctx, durationSec) {
    const sampleRate = ctx.sampleRate;
    const bufferSize = Math.floor(sampleRate * durationSec);
    const buffer = ctx.createBuffer(2, bufferSize, sampleRate);
    const left = buffer.getChannelData(0);
    const right = buffer.getChannelData(1);
    
    // Non-linear Poisson-distributed micro-bubble pops & pebble fizz
    let bubbleEnergyL = 0, bubbleEnergyR = 0;
    for (let i = 0; i < bufferSize; i++) {
      const popTriggerL = Math.random() < 0.0035 ? (Math.random() * 2 - 1) * 2.4 : 0;
      const popTriggerR = Math.random() < 0.0035 ? (Math.random() * 2 - 1) * 2.4 : 0;
      const whiteL = (Math.random() * 2 - 1) * 0.35;
      const whiteR = (Math.random() * 2 - 1) * 0.35;
      
      bubbleEnergyL = (bubbleEnergyL * 0.935) + popTriggerL + (whiteL * 0.12);
      bubbleEnergyR = (bubbleEnergyR * 0.935) + popTriggerR + (whiteR * 0.12);
      
      left[i] = bubbleEnergyL;
      right[i] = bubbleEnergyR;
    }
    return buffer;
  }

