    subFilter.frequency.setValueAtTime(75, audioCtx.currentTime);

    droneGain = audioCtx.createGain();
    droneGain.gain.setValueAtTime(0.005 * volSubBass, audioCtx.currentTime);

    subOsc1.connect(subFilter);
