    const binauralMerger = audioCtx.createChannelMerger(2);
    binauralGainNode = audioCtx.createGain();
    binauralGainNode.gain.setValueAtTime(0.0001, audioCtx.currentTime);
    binauralMerger.connect(binauralGainNode);
